from pathlib import Path
ROOT=Path('/workspace/scratch/2020b62d57db/overlap_validation/Core_Knots_Round12_Overlap_Validation_Evidence_v01/reviewers/C')
pbytes=(ROOT/'packet.json').read_bytes(); packet=json.loads(pbytes)
