units=[]; relations=[]; notes={}; outcomes=[]; mechanisms=[]

def seg(s,start,end=None):
 t=texts[s]; a=t.index(start); return t[a:] if end is None else t[a:t.index(end,a)+len(end)]
def ev(s,q):
 t=texts[s]; a=t.index(q); return {'source_id':s,'span':{'start':a,'end':a+len(q),'quote':q}}
def ue(u): return {'source_id':u['source_id'],'span':u['span']}
def unit(i,s,q,grammar='regulative',speech='proposed',scope='case_specific',typ='undetermined',standing='text_only',force='recommendation',parse='literal',target='operational',obs='operational',rationale='',level='',alternative='',uncertainty='',confidence='plausible',role='statement',quote='none',markup='plain'):
 u={'unit_id':i,'source_id':s,'span':ev(s,q)['span'],'parent_unit_id':None,'grammar':grammar,'speech_act':speech,'scope':scope,'components':[], 'institution':{'type':typ,'standing':standing,'dispute_present':False,'rationale':rationale or 'A contribution-related prescription is expressed; institutional authorization or shared expectation is not thereby established.','evidence':[ev(s,q)],'recognition':[],'authority_evidence':[]},'statement_target_level':target,'observed_action_level':obs,'level_rationale':level or 'The focal action concerns this contribution or review under existing repository arrangements. The visible communication is operational.','complexity_flags':['none'],'alternative_interpretation':alternative,'confidence':confidence,'uncertainty_reason':uncertainty,'record_role':role,'parse_mode':parse,'deontic_force':force,'level_alternatives':[],'template_note':'','presentation':{'quotation':quote,'markup':markup,'rationale':'Presentation is coded from the supplied occurrence; no edit history is assumed.'},'disposition_events':[]}
 if role!='statement':
  u.update(grammar='not_institutional',components=[],statement_target_level='not_applicable',deontic_force='nondeontic'); u['institution'].update(type='not_applicable',standing='not_applicable',rationale=rationale or 'Context or repeated occurrence; not an independent institutional proposition.')
 units.append(u); return u

def comp(u,sym,text,anchor=None,basis='explicit',role='local',note='',refs=None):
 if refs is None:
  q=anchor or text; t=texts[u['source_id']]; start=t.find(q,u['span']['start'],u['span']['end'])
  assert start>=0,(u['unit_id'],sym,q)
  evidence=[{'source_id':u['source_id'],'span':{'start':start,'end':start+len(q),'quote':q}}]
 else: evidence=[ev(s,q) for s,q in refs]
 if u['parse_mode']=='pragmatic' and sym in ['A','Bdir','Bind'] and basis=='explicit' and not note:
  note='The pragmatic force changes the utterance into a recommendation, but this referent retains its overt actor/object role in the stated action.'
 c={'symbol':sym,'text':text,'basis':basis,'evidence':evidence,'inference_note':note,'occurrence_role':role};u['components'].append(c);return c

def inf(u,sym,text,anchor=None,note='',refs=None,role='semantic_inference',basis='context_inferred'):
 return comp(u,sym,text,anchor,basis,role,note,refs)
def rel(a,b,typ,basis='context_inferred',why='',evidence=None,logic='not_applicable'):
 relations.append({'from_unit_id':a['unit_id'],'to_unit_id':b['unit_id'],'type':typ,'basis':basis,'rationale':why,'evidence':evidence or [ue(a),ue(b)],'logic_scope':logic})
def recog(u,kind,target,evidence,why,basis='context_inferred'):
 u['institution']['recognition'].append({'kind':kind,'target':target,'evidence':evidence,'rationale':why,'basis':basis})
def disp(u,kind,target,evidence,why,basis='context_inferred'):
 u['disposition_events'].append({'kind':kind,'target':target,'evidence':evidence,'rationale':why,'basis':basis})
def status(u,pr):
 s='M'+str(pr); m=json.loads(texts[s]); kind='recorded_merged' if m['merged'] else 'recorded_closed_unmerged'
 evidence=[ev(s,'"state": "closed",\n  "merged": '+str(m['merged']).lower())]
 disp(u,kind,'broader_proposal',evidence,'Metadata records the containing PR status; it does not establish acceptance or implementation of every embedded proposition.','explicit')
def ctx(i,s,q=None,**kw): return unit(i,s,texts[s] if q is None else q,role='context',**kw)
def qrec(i,s,q,original):
 u=unit(i,s,q,role='quotation',quote='repeated',speech='other');rel(u,original,'quotes','explicit','Repeated attributed text is linked to the supplied original; it is not another endorsement.');return u

def note(s,reason,missing,alts,sequence=None):
 notes[s]={'reasoning':reason,'missing_context':missing,'consequential_alternatives':alts,'response_recognition_disposition_sequences':sequence or []}

