# Translation freeze: a normative prohibition distinguished from its technical rationale.
s='33224-010'
freezealert=ctx('C224_alert','33224-008',speech='asserted')
qrec('C224_qalert',s,'cc @hebasto; given this would change translations after translation string freeze.',freezealert)
freeze=unit('C224_freeze',s,'In short, there must not be any translation source updates after the final translation string freeze.',speech='asserted',scope='general',typ='norm_candidate',standing='disputed',force='prohibition',rationale='Must not states a categorical process prohibition. The supplied documents do not themselves state this final-freeze prohibition or attribute rule-making authority for it. A later response recognizes the freeze’s purpose but proposes a workaround, contesting absolute application.',alternative='The freeze could be an established rule outside the supplied packet; technical necessity alone does not establish that status.',confidence='clear')
comp(freeze,'D','must not');inf(freeze,'I','update',anchor='translation source updates',note='The nominal updates are rendered as an action; no updater identity is inferred.');inf(freeze,'Bdir','translation sources',anchor='translation source updates',note='The nominal modifier becomes the object of the reconstructed update action.');comp(freeze,'Cac','after the final translation string freeze');freeze['parse_mode']='pragmatic';freeze['institution']['dispute_present']=True
workaround=ctx('C224_workaround','33224-015',seg('33224-015','However, I think there is a workaround','would be suitable.'),speech='asserted')
freezereason=ev('33224-015','I think this issue is why we institute a translation strings freeze.')
recog(freeze,'response','this_proposition',[ue(workaround),freezereason],'The response accepts a freeze rationale but proposes an update that avoids broad invalidation; it does not recognize the categorical no-updates proposition without exception.')
rel(workaround,freeze,'challenges','context_inferred','The technical workaround challenges application of a blanket prohibition to this change while recognizing why the freeze exists.',[ue(workaround),freezereason,ue(freeze)])
fixreport=ctx('C224_fix_report','33224-019',seg('33224-019','I have checked','modified entries:'),speech='reported_action')
rel(workaround,fixreport,'uptake','context_inferred','A later report reproduces the invalidation issue and reports a linked fix. The packet does not prove that the linked fix is identical to every step of the earlier proposed workaround.')
status(freeze,33224)
note(s,'The quote is repeated from the supplied alert. Transifex Reviewed status and lock/reset behavior remain technical context. The final sentence is a real prohibition candidate; authority is unproven. Workaround discussion challenges its absolute application.', ['No explicit freeze-authority provision, exact final freeze date, release exemption decision, or independently verified deployed workaround.'], ['Rule status might exist outside the packet; a purpose-preserving exception differs from abandonment of the freeze.'])

